{"explanation":"An inscribed angle is half the measure of the arc it intercepts. Drag P along the same arc between the fixed endpoints A and B: the triangle changes, but the angle at P stays constant. If P crosses an endpoint onto the other arc, the angle switches to its supplementary angle—here, from 60° to 120°.","manimCode":"const center = [-1.5, 0, 0];
const radius = 2.3;
const tau = 2 * Math.PI;
const alpha = 7 * Math.PI / 6;
const beta = 11 * Math.PI / 6;
let theta = Math.PI / 2;
const onCircle = a => [center[0] + radius * Math.cos(a), center[1] + radius * Math.sin(a), 0];
const A = onCircle(alpha);
const B = onCircle(beta);

const title = new Text({ text: 'The inscribed angle theorem', fontSize: 32, color: WHITE });
title.moveTo([0, 3.2, 0]);
const hint = new Text({ text: 'Drag yellow P — stay on the same arc to keep the angle fixed', fontSize: 20, color: GRAY });
hint.moveTo([0, -3.3, 0]);
const circle = new Circle({ radius, color: BLUE });
circle.moveTo(center);
circle.setStrokeWidth(2);
const endpointA = new Dot({ point: A, color: BLUE, radius: 0.08 });
const endpointB = new Dot({ point: B, color: BLUE, radius: 0.08 });
const handle = new Dot({ point: onCircle(theta), color: YELLOW, radius: 0.13 });
const labelA = new Text({ text: 'A', fontSize: 25, color: BLUE });
const labelB = new Text({ text: 'B', fontSize: 25, color: BLUE });
labelA.moveTo([A[0] - 0.18, A[1] - 0.3, 0]);
labelB.moveTo([B[0] + 0.18, B[1] - 0.3, 0]);
const labelP = new Text({ text: 'P', fontSize: 25, color: YELLOW });
const chordA = new Line({ start: onCircle(theta), end: A, color: WHITE });
const chordB = new Line({ start: onCircle(theta), end: B, color: WHITE });

const arcPieces = [];
for (let i = 0; i < 64; i++) {
  const piece = new Line({ start: A, end: B, color: GOLD });
  piece.setStrokeWidth(5);
  arcPieces.push(piece);
}
const anglePieces = [];
for (let i = 0; i < 20; i++) {
  const piece = new Line({ start: A, end: B, color: YELLOW });
  piece.setStrokeWidth(3);
  anglePieces.push(piece);
}
const angleLabel = new Text({ text: '', fontSize: 22, color: YELLOW });
const arcHeading = new Text({ text: 'Intercepted arc AB', fontSize: 23, color: GOLD });
arcHeading.moveTo([3.6, 1.9, 0]);
const arcReadout = new Text({ text: '', fontSize: 37, color: GOLD });
arcReadout.moveTo([3.6, 1.25, 0]);
const angleHeading = new Text({ text: 'Angle APB', fontSize: 23, color: YELLOW });
angleHeading.moveTo([3.6, 0.3, 0]);
const angleReadout = new Text({ text: '', fontSize: 42, color: YELLOW });
angleReadout.moveTo([3.6, -0.35, 0]);
const formula = new MathTex({ latex: '\\theta = \\tfrac{1}{2}\\,m(\\widehat{AB})', color: WHITE });
await formula.waitForRender();
formula.scale(0.8);
formula.moveTo([3.6, -1.35, 0]);
const note = new Text({ text: 'A and B remain fixed', fontSize: 19, color: GRAY });
note.moveTo([3.6, -2.15, 0]);

scene.add(title, hint, circle, ...arcPieces, chordA, chordB, ...anglePieces, endpointA, endpointB, labelA, labelB, labelP, angleLabel, arcHeading, arcReadout, angleHeading, angleReadout, formula, note, handle);

function update() {
  const P = onCircle(theta);
  handle.moveTo(P);
  labelP.moveTo([P[0] + 0.25 * Math.cos(theta), P[1] + 0.25 * Math.sin(theta), 0]);
  chordA.setStart(P);
  chordB.setStart(P);
  const onMinorArc = theta > alpha && theta < beta;
  const arcStart = onMinorArc ? beta : alpha;
  const arcSweep = onMinorArc ? 4 * Math.PI / 3 : 2 * Math.PI / 3;
  for (let i = 0; i < arcPieces.length; i++) {
    arcPieces[i].setStart(onCircle(arcStart + arcSweep * i / arcPieces.length));
    arcPieces[i].setEnd(onCircle(arcStart + arcSweep * (i + 1) / arcPieces.length));
  }
  const startAngle = Math.atan2(A[1] - P[1], A[0] - P[0]);
  const endAngle = Math.atan2(B[1] - P[1], B[0] - P[0]);
  const sweep = Math.atan2(Math.sin(endAngle - startAngle), Math.cos(endAngle - startAngle));
  const markerRadius = 0.42;
  const markerPoint = a => [P[0] + markerRadius * Math.cos(a), P[1] + markerRadius * Math.sin(a), 0];
  for (let i = 0; i < anglePieces.length; i++) {
    anglePieces[i].setStart(markerPoint(startAngle + sweep * i / anglePieces.length));
    anglePieces[i].setEnd(markerPoint(startAngle + sweep * (i + 1) / anglePieces.length));
  }
  const bisector = startAngle + sweep / 2;
  angleLabel.moveTo([P[0] + 0.76 * Math.cos(bisector), P[1] + 0.76 * Math.sin(bisector), 0]);
  const degrees = onMinorArc ? 120 : 60;
  angleLabel.setText(degrees + '°');
  angleReadout.setText(degrees + '°');
  arcReadout.setText((2 * degrees) + '°');
}
update();

makeDraggable(handle, scene, { onDrag: (mob, pos) => {
  theta = (Math.atan2(pos[1] - center[1], pos[0] - center[0]) + tau) % tau;
  // The angle is undefined at A or B; leave a small gap around each endpoint.
  for (const endpointAngle of [alpha, beta]) {
    const difference = Math.atan2(Math.sin(theta - endpointAngle), Math.cos(theta - endpointAngle));
    if (Math.abs(difference) < 0.12) {
      theta = (endpointAngle + (difference >= 0 ? 0.12 : -0.12) + tau) % tau;
    }
  }
  update();
} });

await scene.wait(999999);"}

